describe('Mark Record as Favourite', () => {
    beforeEach(() => {
        cy.visit('/records'); // Adjust the URL to your application's records page
    });

    it('should successfully mark a record as favourite', () => {
        cy.get('.record').first().within(() => {
            cy.get('.favourite-button').click();
        });
        cy.get('.notification').should('contain', 'Record marked as favourite');
        cy.get('.record').first().should('have.class', 'favourite');
    });

    it('should not allow marking a record as favourite if already marked', () => {
        cy.get('.record').first().within(() => {
            cy.get('.favourite-button').click(); // Mark as favourite
            cy.get('.favourite-button').click(); // Attempt to mark again
        });
        cy.get('.notification').should('contain', 'Record is already marked as favourite');
        cy.get('.record').first().should('have.class', 'favourite');
    });
});
